using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ObscureCustomTag", menuName = "Data/Battle/Battle Actions/Tags/ObscureCustomTag", order = 0)]
public class ObscureCustomTag : Tag
{
	[SerializeField]
	private ObscureEffect obscureEffect;

	public override string GetTagDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAfterFirstCantSeeMeterTagBase(obscureEffect.GetLocalizedDescriptionExternal(), obscureEffect);
	}
}
